import { readFile, writeFile } from "node:fs/promises";
const root = new URL("../", import.meta.url);
const source = await readFile(new URL("packages/cli/lib/runtime-profile.mjs", root), "utf8");
const outputs = [
  [
    "internal/runtimeassets/assets/runtime-profile.js",
    "// Generated by scripts/update-runtime-profile.mjs.\n" + source,
  ],
  [
    "packages/vite-plugin/src/runtime-profile-source.ts",
    "// Generated by scripts/update-runtime-profile.mjs.\nexport const runtimeProfileSource = " +
      JSON.stringify(source) +
      ";\n",
  ],
];
for (const [path, content] of outputs) {
  const url = new URL(path, root);
  if (process.argv.includes("--check")) {
    const actual = await readFile(url, "utf8");
    // Formatting may change the literal's quotes and line wrapping. Compare
    // the exported source so formatting cannot hide a stale runtime policy.
    if (path.endsWith(".ts")) {
      const generated = await import(
        "data:text/javascript;base64," + Buffer.from(actual).toString("base64")
      );
      if (generated.runtimeProfileSource !== source)
        throw new Error("Stale generated runtime profile: " + path);
    } else if (actual !== content) throw new Error("Stale generated runtime profile: " + path);
  } else await writeFile(url, content);
}
